/// `value` raised to a whole power.
///
/// The loop is the same in both configurations, so the two answers agree
/// to the last bit: the dialect cannot depend on the target.
pub(crate) fn powi(value: f64, exponent: i32) -> f64 {
    let mut result = 1.0f64;
    let mut factor = value;
    let mut rest = exponent.unsigned_abs();
    while rest > 0 {
        if rest & 1 == 1 {
            result *= factor;
        }
        factor *= factor;
        rest >>= 1;
    }
    if exponent < 0 { 1.0 / result } else { result }
}

/// The value of a function: an object of the class `Func`.
///
/// A function in a script is a value, and `Func` is the class of it.
fn func_value(name: &str, function: &Function) -> Value {
    // The fewest parameters are the ones that have no default, and the
    // most are all of them.
    let fewest = function
        .parameters
        .iter()
        .filter(|parameter| parameter.is_required())
        .count();
    let mut properties: BTreeMap<String, Property> = BTreeMap::new();
    put(&mut properties, "name", Value::Text(name.to_string().into()));
    put(&mut properties, "minparams", Value::Int(fewest as i64));
    put(
        &mut properties,
        "maxparams",
        Value::Int(function.parameters.len() as i64),
    );
    put(&mut properties, "isbuiltin", Value::Int(0));
    put(&mut properties, "isvariadic", Value::Int(0));
    put(
        &mut properties,
        PARAMETERS,
        the_flags_of_the_parameters(&function.parameters, false),
    );
    Value::Object(SharedCell::new(Object {
        class: "func".to_string(),
        properties,
    }))
}

/// The value of a closure: an object of the class `Func`.
///
/// The name of a closure of v2 is empty, and the name under which the
/// runtime keeps it is in the object and not in the name.
fn closure_value(name: &str, function: &Function, captures: bool) -> Value {
    let value = func_value("", function);
    if let Value::Object(object) = &value {
        let mut object = object.borrow_mut();
        // Measured on the binary of v2.0.19: the class of a
        // function that reads a local of the function that has it is
        // "Closure", and it is a `Func` as well; the class of the other one is
        // "Func".
        if captures {
            object.class = "closure".to_string();
        }
        object.put(CLOSURE, Value::Text(name.to_string().into()));
    }
    value
}

/// Whether a property of a function value is one the runtime carries of
/// its own making -- the name, the number of the parameters, the flags,
/// the closure it keeps -- and not one the script wrote.
///
/// `OwnProps` and `HasOwnProp` do not count these: the own properties of
/// a fresh function are none. A property the script defines over the
/// function (`DefineProp`) is not one of these, and counts as its own.
fn the_intrinsic_member_of_a_function(name: &str) -> bool {
    matches!(
        name,
        "name"
            | "minparams"
            | "maxparams"
            | "isbuiltin"
            | "isvariadic"
            | PARAMETERS
            | CLOSURE
            | BOUND
            | BOUND_TARGET
            | METHOD_CLASS
            | METHOD_NAME
    )
}

/// The value of a built-in: an object of the class `Func`.
///
/// A built-in is a function of the runtime, and it is a value like any
/// other: it can be held in a variable and called through it.
///
/// The most parameters that it takes is the one of the dialect: the v1
/// counts ten thousand for a built-in that takes a variable number of
/// arguments.
fn builtin_value(name: &str, min: u8, max: u32) -> Value {
    let mut properties: BTreeMap<String, Property> = BTreeMap::new();
    put(&mut properties, "name", Value::Text(name.to_string().into()));
    put(&mut properties, "minparams", Value::Int(min as i64));
    put(&mut properties, "maxparams", Value::Int(max as i64));
    put(&mut properties, "isbuiltin", Value::Int(1));
    put(&mut properties, "isvariadic", Value::Int(0));
    Value::Object(SharedCell::new(Object {
        class: "func".to_string(),
        properties,
    }))
}

/// The value of a class: an object of the class itself.
fn class_value(name: &str, class: &Class) -> Value {
    let mut properties: BTreeMap<String, Property> = BTreeMap::new();
    put(&mut properties, CLASS_NAME, Value::Text(class.name.clone().into()));
    put(&mut properties, "prototype", prototype_value(&class.name));
    Value::Object(SharedCell::new(Object {
        class: name.to_lowercase(),
        properties,
    }))
}

/// The value of the parameter that a failure names.
///
/// The text of a parameter of a command of the v1.
///
/// The parameter that wants the name of a variable is a text, and the
/// parameter that is an expression has no name: the shape of the command
/// says which one it is.
fn the_text_of_the_parameter(parameter: &crate::ast::LegacyParameter) -> String {
    match parameter {
        crate::ast::LegacyParameter::Text(text) => text.trim().to_string(),
        crate::ast::LegacyParameter::Expression(_) => String::new(),
    }
}

/// v2 carries the value that a built-in complained about in the `Extra`
/// of the error: the message names the parameter, and the value is the
/// one that was given to it.
fn the_parameter_that_failed(message: &str, values: &[Value]) -> String {
    let Some(rest) = message.strip_prefix("Parameter #") else {
        return String::new();
    };
    let Some((number, _)) = rest.split_once(" of ") else {
        return String::new();
    };
    let Ok(number) = number.parse::<usize>() else {
        return String::new();
    };
    values
        .get(number.saturating_sub(1))
        .map(the_extra_of_the_value)
        .unwrap_or_default()
}

/// The value in the `Extra` of a failure.
///
/// v2 carries the value that arrived, and a text and a number have a text
/// of their own: an object, an array and a function have none.
pub(crate) fn the_extra_of_the_value(value: &Value) -> String {
    match value {
        // Measured on the binary of v2.0.19: a text that is
        // empty is named "empty string" in the `Extra` of a failure, the way
        // the message of the kind of a value names it.
        Value::Text(text) if text.is_empty() => "empty string".to_string(),
        Value::Text(text) => text.to_string(),
        Value::Int(_) | Value::Float(_) => value.to_text(),
        Value::List(_)
        | Value::Object(_)
        | Value::Reference(_)
        | Value::Bytes(_)
        | Value::MapData(_) => String::new(),
        // The absent value has no text of its own, and the dialect refuses it
        // before an Extra carries it.
        Value::Unset | Value::Skipped => String::new(),
    }
}

/// Whether `AHK_TRACE` asks for the line of every statement on stderr.
///
/// The trace is the way into a run that hangs: the statement that never
/// returns is the last line that the trace names.
#[cfg(feature = "std")]
fn the_trace_is_asked() -> bool {
    static THE_ANSWER: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *THE_ANSWER.get_or_init(|| std::env::var_os("AHK_TRACE").is_some())
}

/// The milliseconds that a statement may take before the diagnostic names it.
///
/// `AHK_SLOW=200` names on stderr every statement that takes 200
/// milliseconds or more, with the line and the time of it. The diagnostic
/// is off when the variable is not there, and the cost of it when it is
/// there is one reading of the clock per statement.
#[cfg(feature = "std")]
fn the_slow_threshold() -> u64 {
    static THE_ANSWER: std::sync::OnceLock<u64> = std::sync::OnceLock::new();
    *THE_ANSWER.get_or_init(|| {
        std::env::var("AHK_SLOW")
            .ok()
            .and_then(|value| value.trim().parse::<u64>().ok())
            .unwrap_or(0)
    })
}

#[cfg(not(feature = "std"))]
fn the_slow_threshold() -> u64 {
    0
}

/// The value in the `Extra` of a failure of the maths.
///
/// Measured on the binary of v2.0.19: the operation that wants a number
/// carries the value that arrived, but an empty text carries nothing --
/// `~""` answers "Expected a Number but got an empty string." with an
/// empty `Extra`, while the parameter of a command carries "empty string".
pub(crate) fn the_extra_of_the_value_in_the_maths(value: &Value) -> String {
    match value {
        Value::Text(text) if text.is_empty() => String::new(),
        _ => the_extra_of_the_value(value),
    }
}

/// The prototype of a class: the object that holds its methods.
///
/// v2 gives every class one, and the base of an instance is the prototype
/// of its class.
pub(crate) fn prototype_value(name: &str) -> Value {
    let mut properties: BTreeMap<String, Property> = BTreeMap::new();
    put(&mut properties, CLASS_NAME, Value::Text(name.to_string().into()));
    Value::Object(SharedCell::new(Object {
        class: "prototype".to_string(),
        properties,
    }))
}

/// The format of the whole numbers, the way the dialect formats them.
///
/// Measured on the binary of v1.1.37.02: the format is "D"
/// when the script begins, and the `SetFormat` turns it into "H" or "h".
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum IntegerFormat {
    /// The base ten: 255.
    Decimal,
    /// The base sixteen with the prefix: 0xFF.
    Hexadecimal,
    /// The base sixteen with the prefix and the lower case digits: 0xff.
    HexadecimalLower,
}

impl IntegerFormat {
    /// The name of the format, the way the `A_FormatInteger` says it.
    pub fn name(&self) -> &'static str {
        match self {
            IntegerFormat::Decimal => "D",
            IntegerFormat::Hexadecimal => "H",
            IntegerFormat::HexadecimalLower => "h",
        }
    }

    /// The text of a whole number in this format.
    ///
    /// Measured on the binary of v1.1.37.02: the sign is in
    /// front of the prefix: the -255 is "-0xFF".
    pub fn the_text_of(&self, number: i64) -> String {
        match self {
            IntegerFormat::Decimal => number.to_string(),
            IntegerFormat::Hexadecimal => the_hexadecimal_text_of(number, true),
            IntegerFormat::HexadecimalLower => the_hexadecimal_text_of(number, false),
        }
    }
}

/// The text of a whole number in the base of sixteen.
///
/// Measured on the binary of v1.1.37.02: the sign is in
/// front of the prefix, and not in front of the digits: the -255 is
/// "-0xFF".
fn the_hexadecimal_text_of(number: i64, upper: bool) -> String {
    let sign = if number < 0 { "-" } else { "" };
    let digits = number.unsigned_abs();
    if upper {
        format!("{sign}0x{digits:X}")
    } else {
        format!("{sign}0x{digits:x}")
    }
}

/// The format of the floats, the way the dialect formats them.
///
/// Measured on the binary of v1.1.37.02: the format is "0.6"
/// when the script begins, and it is the width of the text, the number of
/// the decimals and the scientific notation.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct FloatFormat {
    /// The width of the text: the number is padded to it.
    pub width: u32,
    /// The text is padded with zeroes and not with spaces.
    pub zeroes: bool,
    /// The text is justified to the left and not to the right.
    pub left: bool,
    /// The number of the decimals of the text.
    pub decimals: u32,
    /// The text is in the scientific notation.
    pub scientific: bool,
    /// The exponent is in upper case.
    pub upper: bool,
}

impl FloatFormat {
    /// The format of the v1 when the script begins: "0.6".
    pub const DEFAULT: FloatFormat = FloatFormat {
        width: 0,
        zeroes: false,
        left: false,
        decimals: 6,
        scientific: false,
        upper: false,
    };

    /// The name of the format, the way the `A_FormatFloat` says it.
    ///
    /// Measured on the binary of v1.1.37.02: the name is the
    /// format that was written, with the width and the decimals.
    pub fn name(&self) -> String {
        let mut name = String::new();
        if self.left {
            name.push('-');
        }
        if self.zeroes {
            name.push('0');
        }
        name.push_str(&self.width.to_string());
        name.push('.');
        name.push_str(&self.decimals.to_string());
        if self.scientific {
            name.push(if self.upper { 'E' } else { 'e' });
        }
        name
    }

    /// The text of a float in this format.
    ///
    /// The number is rounded to the decimals of the format, and the text is
    /// padded to the width of it.
    pub fn the_text_of(&self, number: f64) -> String {
        // Measured on the binary of v1.1.37.02: the infinity
        // of the v1 is the text of the C library: "1.#INF00" and "-1.#INF00".
        if number.is_infinite() {
            return if number < 0.0 {
                "-1.#INF00".to_string()
            } else {
                "1.#INF00".to_string()
            };
        }
        let decimals = self.decimals as usize;
        let text = if self.scientific {
            let formatted = format!("{:.*e}", decimals, number);
            // The exponent of the v1 has a sign and three digits: `1.0e+003`.
            let (mantissa, exponent) = match formatted.split_once('e') {
                Some((mantissa, exponent)) => (mantissa.to_string(), exponent.to_string()),
                None => (formatted.clone(), String::new()),
            };
            let exponent = match exponent.strip_prefix('-') {
                Some(rest) => format!("-{}", the_digits_of_the_exponent(rest)),
                None => format!("+{}", the_digits_of_the_exponent(&exponent)),
            };
            format!("{mantissa}e{exponent}")
        } else {
            the_text_of_the_number(number, decimals)
        };
        let width = self.width as usize;
        if text.chars().count() >= width {
            return text;
        }
        let padding = width - text.chars().count();
        if self.zeroes {
            // The zeroes go before the number, and the sign keeps its place.
            let (sign, rest) = match text.strip_prefix('-') {
                Some(rest) => ("-", rest),
                None => ("", text.as_str()),
            };
            let mut padded = String::from(sign);
            padded.push_str(&"0".repeat(padding));
            padded.push_str(rest);
            padded
        } else if self.left {
            let mut padded = text;
            padded.push_str(&" ".repeat(padding));
            padded
        } else {
            let mut padded = " ".repeat(padding);
            padded.push_str(&text);
            padded
        }
    }
}

/// The sense of the case, the way the dialect compares the letters.
///
/// Measured on the binary of v1.1.37.02: the sense is "Off"
/// when the script begins, and the `StringCaseSense` turns it into "On" or
/// into "Locale".
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum CaseSense {
    /// The letters A-Z are the same as their lower case, and the others are
    /// not.
    Off,
    /// The letters are taken as they are.
    On,
    /// The letters follow the rules of the locale of the machine.
    Locale,
}

impl CaseSense {
    /// The name of the sense, the way the `A_StringCaseSense` says it.
    pub fn name(&self) -> &'static str {
        match self {
            CaseSense::Off => "Off",
            CaseSense::On => "On",
            CaseSense::Locale => "Locale",
        }
    }

    /// The method that compares two texts.
    ///
    /// Measured on the binary of v1.1.37.02: the sense that is
    /// On takes the letters as they are, and the sense that is Off treats the
    /// letters A-Z as their lower case and the others as they are.
    pub fn the_method(&self) -> CaseMethod {
        match self {
            CaseSense::Off => CaseMethod::Ascii,
            CaseSense::On => CaseMethod::Exact,
            CaseSense::Locale => CaseMethod::Locale,
        }
    }

    /// The method that the equal sign of the v1 uses.
    ///
    /// Measured on the binary of v1.1.37.02: the equal sign is
    /// always without regard to the case, and the method of the locale is the
    /// one it uses when the sense is On: `"ä" = "Ä"` is true when the sense
    /// is On, and it is false when the sense is Off.
    pub fn the_method_of_the_equal_sign(&self) -> CaseMethod {
        match self {
            CaseSense::Off => CaseMethod::Ascii,
            CaseSense::On | CaseSense::Locale => CaseMethod::Locale,
        }
    }
}

/// The method that compares the letters of two texts.
///
/// The method of the locale is the one of the machine, and the tree does
/// not ask the machine for it: it folds the letters of the Unicode, which
/// is the method of the locale of every machine that is written in the
/// Latin alphabet.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum CaseMethod {
    /// The letters A-Z are the same as their lower case, and the others are
    /// not.
    Ascii,
    /// The letters are taken as they are.
    Exact,
    /// The letters follow the rules of the locale of the machine.
    Locale,
}

/// Whether two texts are the same, with the method of the case.
pub(crate) fn the_same_text(left: &str, right: &str, method: CaseMethod) -> bool {
    match method {
        CaseMethod::Ascii => left.eq_ignore_ascii_case(right),
        CaseMethod::Exact => left == right,
        CaseMethod::Locale => left.to_lowercase() == right.to_lowercase(),
    }
}

/// Whether two numbers are the same number.
///
/// The whole numbers are compared as whole numbers: the machine cannot
/// hold every one of them exactly as a float, and the numbers that it
/// rounds are not the same number.
pub(crate) fn the_same_number(left: &Value, right: &Value) -> bool {
    match (left, right) {
        (Value::Int(one), Value::Int(other)) => one == other,
        _ => left.to_number() == right.to_number(),
    }
}

/// Whether the text of the needle is in the text of the haystack, with the
/// method of the case.
///
/// Measured on the binary of v1.1.37.02: the `IfInString` of
/// the v1 finds the text of the needle in the variable, and the sense of the
/// case says whether the letters of them are the same.
pub(crate) fn the_text_contains(haystack: &str, needle: &str, method: CaseMethod) -> bool {
    match method {
        CaseMethod::Ascii => haystack
            .to_ascii_lowercase()
            .contains(&needle.to_ascii_lowercase()),
        CaseMethod::Exact => haystack.contains(needle),
        CaseMethod::Locale => haystack.to_lowercase().contains(&needle.to_lowercase()),
    }
}

/// How two texts stand to each other, with the method of the case.
///
/// Measured on the binary of v1.1.37.02: the texts of the v1
/// are compared letter by letter, and the method of the case says whether
/// the letters of them are the same: `"a" < "B"` is true when the sense is
/// Off, and it is false when the sense is On.
pub(crate) fn the_order_of_the_texts(
    left: &str,
    right: &str,
    method: CaseMethod,
) -> core::cmp::Ordering {
    match method {
        CaseMethod::Ascii => {
            let left = left.to_ascii_lowercase();
            let right = right.to_ascii_lowercase();
            left.cmp(&right)
        }
        CaseMethod::Exact => left.cmp(right),
        CaseMethod::Locale => left.to_lowercase().cmp(&right.to_lowercase()),
    }
}

/// The digits of the exponent of the scientific notation: three at least.
fn the_digits_of_the_exponent(digits: &str) -> String {
    let digits = digits.trim_start_matches('0');
    if digits.is_empty() {
        "000".to_string()
    } else if digits.len() < 3 {
        format!("0{digits:0>2}")
    } else {
        digits.to_string()
    }
}

/// The text of a number, with the decimals of the format.
///
/// Measured on the binary of AutoHotkey v1.1.37.02: the v1
/// writes the number with seventeen digits, and it rounds that number to
/// the decimals of the format -- a half goes away from the zero. The text of
/// the C library writes the digits that the double holds, and the two tell
/// each other apart in the numbers that are big: `Exp(65)` is
/// "16948892444103338000000000000.000000" and not
/// "16948892444103337803358666752.000000".
fn the_text_of_the_number(number: f64, decimals: usize) -> String {
    let negative = number < 0.0;
    // The seventeen digits of the double, and the place of the point.
    let exact = format!("{:.16e}", number.abs());
    let (mantissa, exponent) = match exact.split_once('e') {
        Some((mantissa, exponent)) => (mantissa, exponent),
        None => (exact.as_str(), "0"),
    };
    let digits: String = mantissa
        .chars()
        .filter(|character| character.is_ascii_digit())
        .collect();
    let exponent: i32 = exponent.parse().unwrap_or(0);
    // The number is the digits with the point after `exponent + 1` of them.
    let point = exponent + 1;
    let mut whole = String::new();
    let mut fraction = String::new();
    if point <= 0 {
        whole.push('0');
        for _ in 0..-point {
            fraction.push('0');
        }
        fraction.push_str(&digits);
    } else {
        let point = point as usize;
        if point >= digits.len() {
            whole.push_str(&digits);
            for _ in 0..point - digits.len() {
                whole.push('0');
            }
        } else {
            whole.push_str(&digits[..point]);
            fraction.push_str(&digits[point..]);
        }
    }
    // The rounding: a half goes away from the zero.
    if fraction.len() > decimals {
        if fraction.as_bytes()[decimals] >= b'5' {
            let mut index = decimals;
            let mut carries = true;
            while carries && index > 0 {
                index -= 1;
                let digit = fraction.as_bytes()[index] - b'0';
                if digit == 9 {
                    fraction.replace_range(index..index + 1, "0");
                } else {
                    fraction.replace_range(index..index + 1, &format!("{}", digit + 1));
                    carries = false;
                }
            }
            if carries {
                // The rounding passed the point, and the whole number grows.
                let mut index = whole.len();
                let mut carries = true;
                while carries && index > 0 {
                    index -= 1;
                    let digit = whole.as_bytes()[index] - b'0';
                    if digit == 9 {
                        whole.replace_range(index..index + 1, "0");
                    } else {
                        whole.replace_range(index..index + 1, &format!("{}", digit + 1));
                        carries = false;
                    }
                }
                if carries {
                    whole.insert(0, '1');
                }
            }
        }
        fraction.truncate(decimals);
    } else {
        for _ in fraction.len()..decimals {
            fraction.push('0');
        }
    }
    let mut text = String::new();
    if negative {
        text.push('-');
    }
    text.push_str(&whole);
    if decimals > 0 {
        text.push('.');
        text.push_str(&fraction);
    }
    text
}

/// The failure of the runtime, as the failure of a built-in.
///
/// A built-in answers with a message and a line, and not with the flow
/// of the script: a timeout or a return is not a thing a built-in can
/// hand back.
pub(crate) fn as_error(failure: RuntimeFailure, line: u32) -> RuntimeError {
    match failure {
        RuntimeFailure::Error(error) => error,
        RuntimeFailure::Detailed(error, _) => error,
        _ => RuntimeError {
            message: "the runtime cannot answer that.".into(),
            line,
        },
    }
}

/// The failure of a handler of an event, as the failure of the pump.
///
/// A `return` in a handler ends the handler and not the run that asked
/// for it: the handler runs in the stack of the statement that pumped
/// the machine, and a `return` that came out of it would unwind that
/// statement -- and with it the function that was running.
pub(crate) fn the_failure_of_a_handler(
    failure: RuntimeFailure,
    line: u32,
) -> Option<RuntimeError> {
    match failure {
        RuntimeFailure::Flow(Flow::Return(_)) => None,
        other => Some(as_error(other, line)),
    }
}

/// The fields of a text that is separated the way a CSV file is.
///
/// Measured on the binary of v2.0.19: the separator is the
/// comma; a field that begins with a quote runs to the closing quote, and a
/// pair of quotes inside it is one quote; the text between the closing quote
/// and the comma is dropped; a quote that is not the first character of a
/// field is the quote itself; a quote that is never closed takes the rest of
/// the text; the newline is not a separator; a comma at the end of the text
/// is the empty field after it, and a text that is empty has no field at all.
fn the_fields_of_a_csv(text: &str) -> Vec<String> {
    if text.is_empty() {
        return Vec::new();
    }
    let characters: Vec<char> = text.chars().collect();
    let mut fields = Vec::new();
    let mut index = 0;
    loop {
        let mut field = String::new();
        if characters.get(index) == Some(&'"') {
            index += 1;
            loop {
                match characters.get(index) {
                    None => break,
                    Some('"') => {
                        if characters.get(index + 1) == Some(&'"') {
                            field.push('"');
                            index += 2;
                        } else {
                            index += 1;
                            break;
                        }
                    }
                    Some(character) => {
                        field.push(*character);
                        index += 1;
                    }
                }
            }
            while let Some(character) = characters.get(index) {
                if *character == ',' {
                    break;
                }
                index += 1;
            }
        } else {
            while let Some(character) = characters.get(index) {
                if *character == ',' {
                    break;
                }
                field.push(*character);
                index += 1;
            }
        }
        fields.push(field);
        if characters.get(index) == Some(&',') {
            index += 1;
            if index >= characters.len() {
                fields.push(String::new());
                break;
            }
            continue;
        }
        break;
    }
    fields
}

/// The pieces of a text, cut at every character of the delimiters.
///
/// The pieces keep the order they had, and an empty piece is a piece:
/// the text "a,,b" has three.
pub(crate) fn split_on_any(text: &str, delimiters: &str) -> Vec<String> {
    let mut pieces: Vec<String> = Vec::new();
    let mut current = String::new();
    for character in text.chars() {
        if delimiters.contains(character) {
            pieces.push(core::mem::take(&mut current));
            continue;
        }
        current.push(character);
    }
    pieces.push(current);
    pieces
}

/// Whether two values are equal, the way a script expects.
///
/// A number that came out of an addition is compared with a number that
/// was written down: `2` and `2.0` are the same number, even though one
/// of them is a whole number and the other is not.
fn values_equal(left: &Value, right: &Value, case_sensitive: bool) -> bool {
    values_equal_with(
        left,
        right,
        if case_sensitive {
            CaseMethod::Exact
        } else {
            CaseMethod::Ascii
        },
    )
}

/// Whether two values are equal, with the method of the case.
///
/// The numbers are the same number, and the texts are the same text with
/// the method that the caller asks for.
fn values_equal_with(left: &Value, right: &Value, method: CaseMethod) -> bool {
    // An object is the same object and nothing else.
    //
    // Measured on the binary of v2.0.19: two maps that hold
    // the same entries are not the same map, an instance is not the class
    // of it, and an object is never equal to a value that is not an
    // object -- not even to a text that carries the name of its class.
    //
    // This is a rule of v2: the v1 dialect compares the objects by what
    // they hold, and it bypasses this place.
    if let (Value::Object(one), Value::Object(other)) = (left, right) {
        return SharedCell::ptr_eq(one, other);
    }
    if matches!(left, Value::Object(_)) || matches!(right, Value::Object(_)) {
        return false;
    }

    // Measured on the binary of v2.0.19: two texts are compared
    // as texts -- the "10" and the "10.0" are not the same text -- and a text
    // is compared with a number as a number when the text holds one, the hex
    // of the `0x` prefix included: `513 = "0x201"` and `"0x10" = 16` are one.
    // A text that holds no number is compared with the text of the number:
    // `"" = 0` and `"abc" = 0` are zero.
    match (left, right) {
        (Value::Text(one), Value::Text(other)) => {
            return the_same_text(one, other, method);
        }
        (Value::Text(text), Value::Int(number)) | (Value::Int(number), Value::Text(text)) => {
            return match the_number_of_a_text(text) {
                Some(number_of_the_text) => number_of_the_text == *number as f64,
                None => the_same_text(text, &number.to_string(), method),
            };
        }
        (Value::Text(text), Value::Float(number)) | (Value::Float(number), Value::Text(text)) => {
            return match the_number_of_a_text(text) {
                Some(number_of_the_text) => number_of_the_text == *number,
                None => the_same_text(text, &Value::Float(*number).to_text(), method),
            };
        }
        _ => {}
    }
    if let (Some(a), Some(b)) = (left.to_number(), right.to_number()) {
        return a == b;
    }
    the_same_text(&left.to_text(), &right.to_text(), method)
}

/// Whether the failure is the one of a member that is not there at all.
///
/// The read of a property that has no value is a failure of a different kind,
/// and `IsSet` does not answer it: measured on the test suite of KeySharp (the
/// corpus script `op-null-assign.ahk`), `IsSet(holder.Present.Missing)` answers
/// zero and `IsSet(holder?.Prop)` is an `UnsetError`.
fn the_member_is_missing(failure: &RuntimeFailure) -> bool {
    matches!(
        failure,
        RuntimeFailure::Error(error) | RuntimeFailure::Detailed(error, _)
            if matches!(
                crate::classes::error::the_class_of(&error.message),
                "PropertyError" | "MethodError" | "UnsetItemError"
            )
    )
}

/// Whether the failure is the one of a member that is not there.
///
/// Measured on the test suite of KeySharp (the corpus script
/// `op-null-assign.ahk`) and on the notes of v2.1-alpha: `IsSet` of a member
/// that is not there asks whether it has a value and answers zero -- the
/// member of an object that does not have it, the member of the absent value,
/// and the item that is not there are all of them a "no" -- while a failure of
/// the expression that holds the member is the failure.
fn the_member_is_not_there(failure: &RuntimeFailure) -> bool {
    matches!(
        failure,
        RuntimeFailure::Error(error) | RuntimeFailure::Detailed(error, _)
            if matches!(
                crate::classes::error::the_class_of(&error.message),
                "PropertyError" | "UnsetError" | "UnsetItemError" | "MemberError"
            )
    )
}

/// Whether the failure is the one of a name that has no value.
///
/// The class of the failure is the one of the dialect: the read of a variable
/// that has not been assigned a value is an `UnsetError`, and the two
/// mechanisms of the v2.1 that ask about the absent value are about exactly
/// that failure.
pub(crate) fn the_failure_is_an_unset_variable(failure: &RuntimeFailure) -> bool {
    matches!(
        failure,
        RuntimeFailure::Error(error) | RuntimeFailure::Detailed(error, _)
            if crate::classes::error::the_class_of(&error.message) == "UnsetError"
    )
}

/// The message of a failure, the way the report carries it.
pub(crate) fn the_message_of(failure: &RuntimeFailure) -> String {
    match failure {
        RuntimeFailure::Error(error) => error.message.clone(),
        RuntimeFailure::Detailed(error, _) => error.message.clone(),
        RuntimeFailure::Fatal(error) => error.message.clone(),
        RuntimeFailure::Thrown(value) => thrown_message(value),
        RuntimeFailure::Timeout(timeout) => timeout.to_string(),
        RuntimeFailure::Flow(_) => "the script left a block in the middle of it.".to_string(),
    }
}

/// The number of a property of an object, when it has one.
fn number_of(properties: &BTreeMap<String, Property>, name: &str) -> i64 {
    properties
        .get(name)
        .map(|property| property.value.to_number().unwrap_or(0.0) as i64)
        .unwrap_or(0)
}

/// The key of a static declaration: the line it is on and the name it
/// declares.
///
/// The value of a static declaration runs once, and the key is what tells
/// the tree that it ran.
fn the_key_of_a_declaration(line: u32, name: &str) -> String {
    format!("{}:{}", line, the_key_of(name))
}

/// The key of a variable, as the tree keeps it.
///
/// The dialect does not know the case of the names: `x` and `X` are the
/// same variable. The names of the functions were in lower case already;
/// the variables are like them now.
///
/// A name that is already lower case is borrowed and not copied: the
/// read and the write of a variable are the hot path of a loop, and a
/// name like `x` does not pay for a copy of itself on every turn.
fn the_key_of(name: &str) -> String {
    name.to_lowercase()
}

/// The key of a variable, borrowed when it is already lower case.
///
/// The read and the write of a variable are the hot path of a loop: a
/// name like `x` is its own key, and it is borrowed and not copied. A
/// name that carries a capital is lowered into a key of its own.
/// A lower-cased lookup key that avoids heap allocation for ASCII identifiers
/// up to 64 bytes (which covers virtually every variable and built-in name).
pub(crate) enum LowerKey<'a> {
    Borrowed(&'a str),
    Inline { buf: [u8; 64], len: u8 },
    Owned(String),
}

impl LowerKey<'_> {
    #[inline]
    fn into_owned(self) -> String {
        match self {
            LowerKey::Borrowed(s) => s.to_string(),
            LowerKey::Inline { buf, len } => {
                // SAFETY: all bytes copied from an ASCII `&str` and lowercased as ASCII.
                unsafe { core::str::from_utf8_unchecked(&buf[..len as usize]) }.to_string()
            }
            LowerKey::Owned(s) => s,
        }
    }
}

impl core::ops::Deref for LowerKey<'_> {
    type Target = str;
    #[inline]
    fn deref(&self) -> &str {
        match self {
            LowerKey::Borrowed(s) => s,
            LowerKey::Inline { buf, len } => {
                // SAFETY: all bytes copied from an ASCII `&str` and lowercased as ASCII.
                unsafe { core::str::from_utf8_unchecked(&buf[..*len as usize]) }
            }
            LowerKey::Owned(s) => s.as_str(),
        }
    }
}

#[inline]
pub(crate) fn the_borrowed_key(name: &str) -> LowerKey<'_> {
    if name.is_ascii() {
        let bytes = name.as_bytes();
        if !bytes.iter().any(|byte| byte.is_ascii_uppercase()) {
            return LowerKey::Borrowed(name);
        }
        if bytes.len() <= 64 {
            let mut buf = [0u8; 64];
            for (dst, &src) in buf.iter_mut().zip(bytes) {
                *dst = src.to_ascii_lowercase();
            }
            return LowerKey::Inline {
                buf,
                len: bytes.len() as u8,
            };
        }
    }
    LowerKey::Owned(name.to_lowercase())
}

/// The period of a timer, as the trace of it says it.
///
/// The period of a timer in the trace.
///
/// The trace is a contract with the v1: the v1 writes the period of the
/// timer as it is, and the sign of it says nothing there -- the timer
/// that runs once has a period of its own, and a flag of its own.
///
/// Measured on the v1 that is built for the trace: the
/// `WriteTimer` of the v1 writes the period of the timer (`timer.mPeriod`)
/// and the sign of it is never negative.
fn the_period_in_the_trace(period: u64, once: bool) -> i64 {
    let _ = once;
    period.min(i64::MAX as u64) as i64
}

/// Whether the runtime owns the variable of this name.
///
/// The built-in variables that the runtime writes where it runs -- the
/// line of the statement, the index of the loop -- are not variables of
/// the script, and they change on every statement: the trace of the
/// globals does not carry them.
///
/// The name of the table of the globals is the lower case of the name of
/// the script, and the built-in variables are the ones that begin with
/// `A_`.
fn the_runtime_owns_the_variable(name: &str) -> bool {
    match name.strip_prefix("a_") {
        Some(rest) => crate::variables::THE_RUNTIME_OWNS.contains(&rest),
        None => false,
    }
}

/// Whether the run of the script failed.
///
/// The run that ended with a jump -- a `break`, a `continue` or a
/// `return` -- did not fail: the script ended the way it asked. Every
/// other ending is a failure, and a run that failed does not stay alive.
fn the_run_failed(outcome: &Result<(), RuntimeFailure>) -> bool {
    match outcome {
        Ok(()) => false,
        Err(RuntimeFailure::Flow(Flow::Break(_)))
        | Err(RuntimeFailure::Flow(Flow::Continue(_)))
        | Err(RuntimeFailure::Flow(Flow::Return(_))) => false,
        Err(_) => true,
    }
}

/// The message of a value that was thrown and that nobody caught.
///
/// A text is the message of the exception, the way v2 shows it, and
/// anything else is the message of an exception without a name.
fn thrown_message(value: &Value) -> String {
    match value {
        Value::Text(text) => format!("Unhandled exception.\n     Specifically: {text}"),
        // Measured on the binary of v2.0.19: the dialog of an
        // uncaught error shows the message of the error -- `throw
        // Error("boom")` shows "boom" -- and the report of the runner carries
        // the same text, so a tool that reads it learns what the script threw
        // instead of a generic line.
        Value::Object(object) => {
            let borrowed = object.borrow();
            if crate::classes::error::is_a_class(&borrowed.class) {
                if let Some(Value::Text(message)) = borrowed.value_of("message") {
                    if !message.is_empty() {
                        return message.into_string();
                    }
                }
            }
            "Unhandled exception.".to_string()
        }
        _ => "Unhandled exception.".to_string(),
    }
}

/// The place of the label in a block, when the block holds it.
///
/// The names of the labels do not know their case, the way the names of the
/// variables do not.
fn the_place_of_the_label(statements: &[Node], name: &str) -> Option<usize> {
    statements.iter().position(|statement| match statement {
        Node::Label { name: label, .. } => label.eq_ignore_ascii_case(name),
        _ => false,
    })
}

/// The name of the window of the script, from the name of the label of the
/// event.
///
/// The label of the event of the v1 is the name of the window and the
/// `GuiSize` of it. The window of the script without a name is the window
/// number one, and the label of it is the `GuiSize` of it.
///
/// Measured on the binary of v1.1.37.02: the `A_Gui` of the label
/// `PVwinGuiSize` of the window `PVwin` is `PVwin`, and the `A_Gui` of the
/// label `GuiSize` of the window of the script without a name is `1`.
fn the_name_of_the_gui(label: &str) -> String {
    const THE_SUFFIX: &str = "GuiSize";
    if label.len() > THE_SUFFIX.len()
        && label[label.len() - THE_SUFFIX.len()..].eq_ignore_ascii_case(THE_SUFFIX)
    {
        return label[..label.len() - THE_SUFFIX.len()].to_string();
    }
    "1".to_string()
}

/// The built-in variables of the event of the window of the script.
///
/// The v1 gives them to the thread that the event launches, and a function
/// of the script reads them there: the scope of a function of the v1 is its
/// own, and the built-in variables of the event are the ones that the
/// machine owns.
///
/// Measured on the binary of v1.1.37.02: the function `PVwinGuiSize` of a
/// window that is resized reads `A_GuiWidth` and `A_GuiHeight` with the
/// size of the client area of the window, and `A_Gui` with the name of it.
const THE_BUILT_INS_OF_THE_EVENT: &[&str] = &[
    "a_guiwidth",
    "a_guiheight",
    "a_gui",
    "a_eventinfo",
];

/// The labels of a scope, the way the script wrote them.
///
/// The labels of a function are the ones of its body, and the body of a
/// function that is written inside another one belongs to the function it
/// is written in.
fn the_labels_of(body: &[Node]) -> Vec<String> {
    let mut labels = Vec::new();
    collect_the_labels(body, &mut labels);
    labels
}

/// The names that the parameters of a function take.
///
/// The names of the v1 do not know their case.
fn the_names_of_the_parameters(parameters: &[Parameter]) -> BTreeSet<String> {
    parameters
        .iter()
        .map(|parameter| parameter.name.to_lowercase())
        .collect()
}

/// Whether the body of a function is in the force-local mode.
///
/// Measured on the binary of AutoHotkey v1.1.37.02: the mode
/// is the bare `local` of the first line of the body, and a super-global of
/// the script is not reachable in it -- the `f() { local  gv := 42 }`
/// leaves the global of `gv` at its value.
fn the_body_is_in_the_force_local_mode(body: &[Node]) -> bool {
    matches!(
        body.first(),
        Some(Node::Declare {
            scope: DeclareKind::Local,
            names,
            ..
        }) if names.is_empty()
    )
}

/// The names that the `global` declarations outside of any function
/// declare.
///
/// Measured on the binary of AutoHotkey v1.1.37.02: the
/// `Global gv := 1` of the top level of a script declares `gv` for every
/// function of the script, and the `gv := 42` of a function writes that
/// global. A name that the top level of the script only *writes* -- the
/// `gv := 1` without the declaration -- is not one of them: the function
/// that writes it writes a local of its own.
///
/// The walk does not go into the body of a function, of a method or of a
/// hotkey: a `global` declaration there is the declaration of that
/// function and not the declaration of the script.
fn the_super_globals_of_the_script(statements: &[Node]) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    the_super_globals_of_a_level(statements, &mut names);
    names
}

/// The names that the `global` declarations of a level of the script
/// declare.
fn the_super_globals_of_a_level(statements: &[Node], names: &mut BTreeSet<String>) {
    for statement in statements {
        match statement {
            Node::Declare {
                scope: DeclareKind::Global,
                names: declared,
                ..
            } => {
                for declared in declared {
                    names.insert(declared.name.to_lowercase());
                }
            }
            Node::Block { body, .. } => the_super_globals_of_a_level(body, names),
            Node::LegacyIf {
                body, otherwise, ..
            } => {
                the_super_globals_of_a_level(body, names);
                the_super_globals_of_a_level(otherwise, names);
            }
            Node::If {
                branches,
                otherwise,
                ..
            } => {
                for branch in branches {
                    the_super_globals_of_a_level(&branch.body, names);
                }
                the_super_globals_of_a_level(otherwise, names);
            }
            Node::Switch { cases, .. } => {
                for case in cases {
                    the_super_globals_of_a_level(&case.body, names);
                }
            }
            Node::While { body, otherwise, .. }
            | Node::Loop { body, otherwise, .. }
            | Node::For { body, otherwise, .. } => {
                the_super_globals_of_a_level(body, names);
                if let Some(otherwise) = otherwise {
                    the_super_globals_of_a_level(otherwise, names);
                }
            }
            Node::Try {
                body,
                catches,
                otherwise,
                finally,
                ..
            } => {
                the_super_globals_of_a_level(body, names);
                for catch in catches {
                    the_super_globals_of_a_level(&catch.body, names);
                }
                the_super_globals_of_a_level(otherwise, names);
                the_super_globals_of_a_level(finally, names);
            }
            _ => {}
        }
    }
}

/// The labels of the blocks of a body.
fn collect_the_labels(body: &[Node], labels: &mut Vec<String>) {
    for statement in body {
        match statement {
            Node::Label { name, .. } => labels.push(name.clone()),
            // The body of a hotkey of the v1 is of the scope that carries
            // it: the hotkey is not a block, and a jump may leave it.
            Node::HotkeyDefinition { body, .. } => collect_the_labels(body, labels),
            Node::If {
                branches,
                otherwise,
                ..
            } => {
                for branch in branches {
                    collect_the_labels(&branch.body, labels);
                }
                collect_the_labels(otherwise, labels);
            }
            Node::Switch { cases, .. } => {
                for case in cases {
                    collect_the_labels(&case.body, labels);
                }
            }
            Node::Block { body, .. }
            | Node::While { body, .. }
            | Node::Loop { body, .. }
            | Node::For { body, .. } => {
                collect_the_labels(body, labels);
            }
            Node::LegacyIf {
                body, otherwise, ..
            } => {
                collect_the_labels(body, labels);
                collect_the_labels(otherwise, labels);
            }
            Node::Try {
                body,
                catches,
                otherwise,
                finally,
                ..
            } => {
                collect_the_labels(body, labels);
                for catch in catches {
                    collect_the_labels(&catch.body, labels);
                }
                collect_the_labels(otherwise, labels);
                collect_the_labels(finally, labels);
            }
            _ => {}
        }
    }
}

/// The built-in of this name, in the dialect that runs.
///
/// The name is matched the way AutoHotkey matches it: without regard
/// to the case.
/// O(1) built-in lookup cache keyed by the static dialect slice pointer.
#[cfg(feature = "std")]
struct BuiltinIndex {
    any: std::collections::HashMap<
        String,
        &'static crate::builtins::Builtin,
        crate::fast_hash::FastHasherBuilder,
    >,
    by_kind: std::collections::HashMap<
        (String, u8),
        &'static crate::builtins::Builtin,
        crate::fast_hash::FastHasherBuilder,
    >,
}

#[cfg(feature = "std")]
fn builtin_kind_tag(kind: crate::builtins::BuiltinKind) -> u8 {
    match kind {
        crate::builtins::BuiltinKind::Command => 0,
        crate::builtins::BuiltinKind::Function => 1,
    }
}

#[cfg(feature = "std")]
fn lookup_builtin_fast(
    builtins: &'static [crate::builtins::Builtin],
    name: &str,
    preferred: Option<crate::builtins::BuiltinKind>,
) -> Option<&'static crate::builtins::Builtin> {
    use std::cell::Cell;
    use std::sync::{OnceLock, RwLock};
    static CACHE: OnceLock<RwLock<Vec<(usize, &'static BuiltinIndex)>>> = OnceLock::new();
    std::thread_local! {
        static LAST_INDEX: Cell<(usize, Option<&'static BuiltinIndex>)> = const { Cell::new((0, None)) };
    }
    let ptr = builtins.as_ptr() as usize;
    let index: &'static BuiltinIndex = match LAST_INDEX.with(|cell| {
        let (cached_ptr, cached_idx) = cell.get();
        if cached_ptr == ptr {
            cached_idx
        } else {
            None
        }
    }) {
        Some(idx) => idx,
        None => {
            let cache = CACHE.get_or_init(|| RwLock::new(Vec::new()));
            let guard = cache.read().unwrap();
            let idx = if let Some(&(_, idx)) = guard.iter().find(|&&(p, _)| p == ptr) {
                idx
            } else {
                drop(guard);
                let mut write = cache.write().unwrap();
                if let Some(&(_, idx)) = write.iter().find(|&&(p, _)| p == ptr) {
                    idx
                } else {
                    // The hash of the names of the built-ins is a fast
                    // one: the table is looked up in every call.
                    let mut any: std::collections::HashMap<
                        String,
                        &'static crate::builtins::Builtin,
                        crate::fast_hash::FastHasherBuilder,
                    > = std::collections::HashMap::with_hasher(
                        crate::fast_hash::FastHasherBuilder::default(),
                    );
                    any.reserve(builtins.len());
                    let mut by_kind: std::collections::HashMap<
                        (String, u8),
                        &'static crate::builtins::Builtin,
                        crate::fast_hash::FastHasherBuilder,
                    > = std::collections::HashMap::with_hasher(
                        crate::fast_hash::FastHasherBuilder::default(),
                    );
                    by_kind.reserve(builtins.len());
                    for b in builtins {
                        let key = b.name.to_lowercase();
                        any.entry(key.clone()).or_insert(b);
                        by_kind.entry((key, builtin_kind_tag(b.kind))).or_insert(b);
                    }
                    let leaked: &'static BuiltinIndex =
                        Box::leak(Box::new(BuiltinIndex { any, by_kind }));
                    write.push((ptr, leaked));
                    leaked
                }
            };
            LAST_INDEX.with(|cell| cell.set((ptr, Some(idx))));
            idx
        }
    };
    let key = the_borrowed_key(name);
    if let Some(kind) = preferred {
        // Fast check: most built-ins have a unique name, so check `any` first
        // without allocating a `(String, u8)` tuple key.
        if let Some(&first) = index.any.get(&*key) {
            if first.kind == kind {
                return Some(first);
            }
            if let Some(&typed) = index.by_kind.get(&(key.into_owned(), builtin_kind_tag(kind))) {
                return Some(typed);
            }
            return Some(first);
        }
        return None;
    }
    index.any.get(&*key).copied()
}

/// Whether a statement list contains any nested `FunctionDef`.
fn body_has_nested_functions(statements: &[Node]) -> bool {
    statements.iter().any(|statement| match statement {
        Node::FunctionDef { .. } => true,
        Node::Block { body, .. } => body_has_nested_functions(body),
        Node::LegacyIf {
            body, otherwise, ..
        } => body_has_nested_functions(body) || body_has_nested_functions(otherwise),
        Node::If {
            branches,
            otherwise,
            ..
        } => {
            branches
                .iter()
                .any(|branch| body_has_nested_functions(&branch.body))
                || body_has_nested_functions(otherwise)
        }
        Node::Switch { cases, .. } => cases.iter().any(|case| body_has_nested_functions(&case.body)),
        Node::While { body, .. } | Node::Loop { body, .. } => body_has_nested_functions(body),
        Node::Try {
            body,
            catches,
            otherwise,
            finally,
            ..
        } => {
            body_has_nested_functions(body)
                || catches
                    .iter()
                    .any(|catch| body_has_nested_functions(&catch.body))
                || body_has_nested_functions(otherwise)
                || body_has_nested_functions(finally)
        }
        _ => false,
    })
}

/// Pre-compiled expression for counted fast loops.
enum FastExpr<'b> {
    Int(i64),
    Float(f64),
    Reg(usize, u32),
    AIndex,
    Unary {
        op: crate::ast::UnaryOp,
        operand: Box<FastExpr<'b>>,
        line: u32,
    },
    Binary {
        op: BinaryOp,
        left: Box<FastExpr<'b>>,
        right: Box<FastExpr<'b>>,
        line: u32,
    },
    NumGet {
        source: Box<FastExpr<'b>>,
        offset: Box<FastExpr<'b>>,
        kind: crate::dll::NativeType,
        line: u32,
    },
    /// The write of a number into a buffer: `NumPut("Int64", 1, buf, 0)`.
    ///
    /// The type of the number is a name of the source, and it is resolved
    /// when the loop is compiled: the name is not matched in every turn.
    /// The value, the target and the offset are the values of the loop.
    NumPut {
        value: Box<FastExpr<'b>>,
        target: Box<FastExpr<'b>>,
        offset: Box<FastExpr<'b>>,
        kind: crate::dll::NativeType,
        line: u32,
    },
    BufferPtr {
        target: usize,
        line: u32,
    },
    Prop {
        target: usize,
        reg_line: u32,
        name: Text,
        key: String,
        line: u32,
    },
    Index {
        target: usize,
        target_line: u32,
        index: Box<FastExpr<'b>>,
        line: u32,
    },
    /// The call of a method of a value: `c.Inc(1)`.
    ///
    /// The name of the method is the text of the source, and it is read
    /// where it is written: the name is not looked up in every turn. The
    /// target of the call is the value of an expression of the loop, and
    /// the arguments are read by the call of the method itself, the way
    /// the generic path reads them.
    MethodCall {
        target: Box<FastExpr<'b>>,
        name: Text,
        arguments: &'b [Node],
        line: u32,
    },
    /// The call of a function of the script: `f(1)`.
    ///
    /// The name of the function is the text of the source, and it is read
    /// where it is written. The arguments are the values of the loop, and
    /// they are read from the registers of it.
    FuncCall {
        name: Text,
        arguments: Vec<FastExpr<'b>>,
        line: u32,
    },
    /// The call of a built-in, with the row of it resolved when the loop was
    /// compiled.
    ///
    /// The official compiles the call site too, and the name of the call is
    /// not looked up in every turn: the row of the built-in is known when
    /// the loop is compiled, and the arguments are the ones of the loop.
    Builtin {
        builtin: &'static crate::builtins::Builtin,
        arguments: Vec<FastExpr<'b>>,
        wants: Option<Box<[crate::builtins::Wants]>>,
        line: u32,
    },
    /// A text of a literal, with the text of it copied when the loop was
    /// compiled.
    ///
    /// The text is read where it is written, the way the generic path reads
    /// it: the name of a variable in it is the name of the scope that writes
    /// it.
    Text(Text),
    InterpolatedText(Text, u32),
}

/// Branch body inside a compiled fast loop: either compiled register statements
/// or a cold AST slice executed via `run_block` when the branch is taken.
enum FastBranch<'a> {
    Fast(Vec<FastStmt<'a>>),
    Cold(&'a [Node]),
}

/// Pre-compiled statement for counted fast loops.
enum FastStmt<'a> {
    Assign {
        target: usize,
        op: AssignOp,
        value: FastExpr<'a>,
        line: u32,
    },
    IncDec {
        target: usize,
        delta: i64,
        line: u32,
    },
    If {
        condition: FastExpr<'a>,
        then_branch: FastBranch<'a>,
        else_branch: Option<FastBranch<'a>>,
    },
    Expr(FastExpr<'a>),
    AssignProp {
        target: usize,
        target_line: u32,
        name: Text,
        key: String,
        op: AssignOp,
        value: FastExpr<'a>,
        line: u32,
    },
    ArrayPush {
        target: usize,
        target_line: u32,
        method_name: &'a str,
        arg: FastExpr<'a>,
        raw_args: &'a [Node],
        line: u32,
    },
    AssignIndex {
        target: usize,
        target_line: u32,
        index: FastExpr<'a>,
        op: AssignOp,
        value: FastExpr<'a>,
        line: u32,
    },
}

/// Control flow returned by executing a slice of `FastStmt`s.
enum FastFlow {
    Next,
    Continue,
    Break,
}

/// Per-loop caches for `NumGet`, `Buffer.Ptr`, plain objects, `Array`, and `Map`, invalidated on cold blocks or pumps.
#[derive(Default)]
struct FastCaches {
    mirror_cell: Option<SharedCell<Vec<u8>>>,
    buf_cell: Option<(usize, SharedCell<Vec<u8>>)>,
    buf_ptr: Option<(usize, i64)>,
    plain_obj_id: Option<usize>,
    arr_state: Option<(usize, SharedCell<Object>)>,
    map_state: Option<(usize, SharedCell<crate::classes::map::MapData>)>,
}

impl FastCaches {
    #[inline]
    fn clear(&mut self) {
        self.mirror_cell = None;
        self.buf_cell = None;
        self.buf_ptr = None;
        self.plain_obj_id = None;
        self.arr_state = None;
        self.map_state = None;
    }
}

enum FastForCollection {
    Array(SharedCell<Object>),
    Map(SharedCell<crate::classes::map::MapData>),
}

struct CompiledFastFor<'a> {
    loop_body: CompiledFastLoop<'a>,
    arity: usize,
    var0: Option<usize>,
    var1: Option<usize>,
}

/// Working state while compiling a counted loop onto register slots.
struct FastCompiler {
    is_local: bool,
    allow_v2: bool,
    allow_numget: bool,
    names: Vec<String>,
    keys: Vec<String>,
    written: Vec<bool>,
}

/// A counted loop body compiled onto flat register slots.
struct CompiledFastLoop<'a> {
    names: Vec<String>,
    keys: Vec<String>,
    written: Vec<bool>,
    stmts: Vec<FastStmt<'a>>,
    is_local: bool,
    line: u32,
}

pub fn the_builtin_in(
    dialect: &'static dyn crate::dialect::Dialect,
    name: &str,
) -> Option<&'static crate::builtins::Builtin> {
    let builtins = dialect.builtins();
    #[cfg(feature = "std")]
    {
        if let Some(found) = lookup_builtin_fast(builtins, name, None) {
            return Some(found);
        }
        let wanted = the_borrowed_key(name);
        dialect.the_builtin_of_the_extension(&wanted)
    }
    #[cfg(not(feature = "std"))]
    {
        builtins
            .iter()
            .find(|builtin| builtin.name.eq_ignore_ascii_case(name))
            .or_else(|| {
                let wanted = the_borrowed_key(name);
                dialect.the_builtin_of_the_extension(&wanted)
            })
    }
}

/// The reason of a failure, in the text that the trace shows.
///
/// The step that failed keeps the reason in its detail: the trace of a
/// run that fails says what failed, and the line of it.
fn the_reason_of_the_failure(failure: &RuntimeFailure) -> String {
    match failure {
        RuntimeFailure::Error(error) => error.message.clone(),
        RuntimeFailure::Detailed(error, detail) => {
            if detail.extra.is_empty() {
                error.message.clone()
            } else {
                format!("{} {}", error.message, detail.extra)
            }
        }
        RuntimeFailure::Fatal(error) => error.message.clone(),
        RuntimeFailure::Thrown(value) => value.to_text(),
        RuntimeFailure::Timeout(timeout) => {
            format!("the script ran for more than {} seconds", timeout.seconds)
        }
        RuntimeFailure::Flow(_) => String::new(),
    }
}

/// The time a step takes to be in the list of the slow ones of the report.
///
/// `AHK_SLOW` says the threshold, and it is the one of the diagnostic
/// that names the slow statements on stderr. Without it, the list of the
/// report takes the steps that took more than a tenth of a second.
fn the_threshold_of_the_slow_list() -> u64 {
    let asked = the_slow_threshold();
    if asked > 0 {
        return asked;
    }
    Runtime::SLOW_STEP_MS
}

/// Whether the type of an argument of a native call is a text.
///
/// The type is the text that names it, and the text of a native call is
/// the buffer of the variable of the caller.
fn the_type_is_a_text(kind: &Value) -> bool {
    let Value::Text(text) = kind else {
        return false;
    };
    crate::dll::parse_type(text).is_some_and(|(kind, _)| kind.is_text())
}

/// The name a statement is reported under.
pub fn op_name(statement: &Node) -> &str {
    op_name_in(statement, crate::dialect::v2())
}

/// The name a statement is reported under, borrowing static names without
/// heap allocation in the common v2/v1 execution path.
fn op_name_cow(
    statement: &Node,
    dialect: &'static dyn crate::dialect::Dialect,
) -> alloc::borrow::Cow<'static, str> {
    use alloc::borrow::Cow;
    match statement {
        Node::LegacyCall { name, .. }
        | Node::LegacyIf { name, .. }
        | Node::Directive { name, .. } => Cow::Owned(name.clone()),
        Node::Call { name, .. } => match the_builtin_in(dialect, name) {
            Some(builtin) => Cow::Borrowed(builtin.name),
            None => Cow::Borrowed("Call"),
        },
        Node::Expression { value, .. } => match the_call_of(value) {
            Some(name) => match the_builtin_in(dialect, name) {
                Some(builtin) => Cow::Borrowed(builtin.name),
                None => Cow::Borrowed("Call"),
            },
            None => Cow::Borrowed("Expression"),
        },
        Node::VarRef { .. } => Cow::Borrowed("VarRef"),
        Node::Assign { .. } => Cow::Borrowed("Assign"),
        Node::AssignIndex { .. } => Cow::Borrowed("AssignIndex"),
        Node::CallDynamic { .. } => Cow::Borrowed("CallDynamic"),
        Node::New { .. } => Cow::Borrowed("New"),
        Node::Block { .. } => Cow::Borrowed("Block"),
        Node::If { .. } => Cow::Borrowed("If"),
        Node::Switch { .. } => Cow::Borrowed("Switch"),
        Node::While { .. } => Cow::Borrowed("While"),
        Node::Try { .. } => Cow::Borrowed("Try"),
        Node::Throw { .. } => Cow::Borrowed("Throw"),
        Node::Declare { .. } => Cow::Borrowed("Declare"),
        Node::Super { .. } => Cow::Borrowed("Super"),
        Node::Loop { .. } => Cow::Borrowed("Loop"),
        Node::ArrayLiteral { .. } => Cow::Borrowed("ArrayLiteral"),
        Node::ObjectLiteral { .. } => Cow::Borrowed("ObjectLiteral"),
        Node::Lambda { .. } => Cow::Borrowed("Lambda"),
        Node::For { .. } => Cow::Borrowed("For"),
        Node::Break { .. } => Cow::Borrowed("Break"),
        Node::Continue { .. } => Cow::Borrowed("Continue"),
        Node::Spread { .. } => Cow::Borrowed("Spread"),
        Node::Label { .. } => Cow::Borrowed("Label"),
        Node::Goto { .. } => Cow::Borrowed("Goto"),
        Node::Gosub { .. } => Cow::Borrowed("Gosub"),
        Node::GotoComputed { .. } => Cow::Borrowed("GotoComputed"),
        Node::HotkeyDefinition { .. } => Cow::Borrowed("HotkeyDefinition"),
        Node::Return { .. } => Cow::Borrowed("Return"),
        Node::ExitApp { .. } => Cow::Borrowed("ExitApp"),
        Node::FunctionDef { .. } => Cow::Borrowed("FunctionDef"),
        Node::ClassDef { .. } => Cow::Borrowed("ClassDef"),
        Node::MethodCall { .. } => Cow::Borrowed("MethodCall"),
        Node::CallValue { .. } => Cow::Borrowed("CallValue"),
        Node::Property { .. } => Cow::Borrowed("Property"),
        Node::AssignProperty { .. } => Cow::Borrowed("AssignProperty"),
        Node::AssignCall { .. } => Cow::Borrowed("AssignCall"),
        Node::Literal { .. } => Cow::Borrowed("Literal"),
        Node::Var { .. } => Cow::Borrowed("Var"),
        Node::Unary { .. } => Cow::Borrowed("Unary"),
        Node::Binary { .. } => Cow::Borrowed("Binary"),
        Node::Unset { .. } => Cow::Borrowed("Unset"),
        Node::Ternary { .. } => Cow::Borrowed("Ternary"),
        Node::DynamicName { .. } => Cow::Borrowed("DynamicName"),
        Node::AssignDynamic { .. } => Cow::Borrowed("AssignDynamic"),
        Node::Index { .. } => Cow::Borrowed("Index"),
        Node::Group { .. } => Cow::Borrowed("Group"),
        Node::Maybe { .. } => Cow::Borrowed("Maybe"),
        Node::Empty { .. } => Cow::Borrowed("Empty"),
        Node::Legacy { .. } => Cow::Borrowed("Legacy"),
        Node::LegacyExpression { .. } => Cow::Borrowed("LegacyExpression"),
        Node::LegacyControl { .. } => Cow::Borrowed("LegacyControl"),
        Node::LegacyAssign { .. } => Cow::Borrowed("LegacyAssign"),
        Node::LegacyComparison { .. } => Cow::Borrowed("LegacyComparison"),
        Node::LegacyMatch { .. } => Cow::Borrowed("LegacyMatch"),
    }
}

/// The name a statement is reported under, in the dialect of the run.
pub fn op_name_in<'a>(
    statement: &'a Node,
    dialect: &'static dyn crate::dialect::Dialect,
) -> &'a str {
    match statement {
        Node::VarRef { .. } => "VarRef",
        Node::Assign { .. } => "Assign",
        Node::AssignIndex { .. } => "AssignIndex",
        // A call to a built-in is reported under the name of the built-in,
        // the way AutoHotkey reports a command.
        Node::Call { name, .. } => match the_builtin_in(dialect, name) {
            Some(builtin) => builtin.name,
            None => "Call",
        },
        Node::CallDynamic { .. } => "CallDynamic",
        // The legacy command of the v1 is reported under its own name.
        Node::LegacyCall { name, .. } => name,
        // The `new` of the v1 is reported under its own name.
        Node::New { .. } => "New",
        // The command of the v1 that has a body is reported under its own
        // name as well.
        Node::LegacyIf { name, .. } => name,
        Node::Expression { value, .. } => match the_call_of(value) {
            // The statement reads the member of the answer of a call, and
            // it is still the call that the report names.
            Some(name) => match the_builtin_in(dialect, name) {
                Some(builtin) => builtin.name,
                None => "Call",
            },
            None => "Expression",
        },
        Node::Block { .. } => "Block",
        Node::If { .. } => "If",
        Node::Switch { .. } => "Switch",
        Node::While { .. } => "While",
        Node::Try { .. } => "Try",
        Node::Throw { .. } => "Throw",
        Node::Declare { .. } => "Declare",
        Node::Super { .. } => "Super",
        Node::Loop { .. } => "Loop",
        Node::ArrayLiteral { .. } => "ArrayLiteral",
        Node::ObjectLiteral { .. } => "ObjectLiteral",
        Node::Lambda { .. } => "Lambda",
        Node::For { .. } => "For",
        Node::Directive { name, .. } => name,
        Node::Break { .. } => "Break",
        Node::Continue { .. } => "Continue",
        // The spread is an argument of a call and not a statement, and the
        // report names one when it is read outside a list of arguments.
        Node::Spread { .. } => "Spread",
        Node::Label { .. } => "Label",
        Node::Goto { .. } => "Goto",
        Node::Gosub { .. } => "Gosub",
        Node::GotoComputed { .. } => "GotoComputed",
        Node::HotkeyDefinition { .. } => "HotkeyDefinition",
        Node::Return { .. } => "Return",
        Node::ExitApp { .. } => "ExitApp",
        Node::FunctionDef { .. } => "FunctionDef",
        Node::ClassDef { .. } => "ClassDef",
        Node::MethodCall { .. } => "MethodCall",
        Node::CallValue { .. } => "CallValue",
        Node::Property { .. } => "Property",
        Node::AssignProperty { .. } => "AssignProperty",
        Node::AssignCall { .. } => "AssignCall",
        Node::Literal { .. } => "Literal",
        Node::Var { .. } => "Var",
        Node::Unary { .. } => "Unary",
        Node::Binary { .. } => "Binary",
        Node::Unset { .. } => "Unset",
        Node::Ternary { .. } => "Ternary",
        Node::DynamicName { .. } => "DynamicName",
        Node::AssignDynamic { .. } => "AssignDynamic",
        Node::Index { .. } => "Index",
        Node::Group { .. } => "Group",
        Node::Maybe { .. } => "Maybe",
        Node::Empty { .. } => "Empty",
        Node::Legacy { .. } => "Legacy",
        Node::LegacyExpression { .. } => "LegacyExpression",
        Node::LegacyControl { .. } => "LegacyControl",
        Node::LegacyAssign { .. } => "LegacyAssign",
        Node::LegacyComparison { .. } => "LegacyComparison",
        Node::LegacyMatch { .. } => "LegacyMatch",
    }
}

/// The call that a value holds, when it holds one.
///
/// A statement that reads the member of the answer of a call is the call
/// itself: `Map().Count` is the call of `Map` and the reading of a member.
fn the_call_of(node: &Node) -> Option<&str> {
    match node {
        Node::Call { name, .. } => Some(name),
        Node::Property { target, .. }
        | Node::Index { target, .. }
        | Node::MethodCall { target, .. } => the_call_of(target),
        _ => None,
    }
}

pub(crate) enum RuntimeFailure {
    Error(RuntimeError),
    /// A failure with the detail that v2 carries in the error object.
    ///
    /// `What` names the thing that raised the failure, and `Extra` is
    /// the detail that goes with it.
    Detailed(RuntimeError, Detail),
    /// A failure that no catch takes.
    ///
    /// Measured on the binary of v2.0.19: the failure of a
    /// `Goto` that does not find its label ends the script, and a catch
    /// does not take it.
    Fatal(RuntimeError),
    /// A value that the script threw.
    Thrown(Value),
    Timeout(Timeout),
    Flow(Flow),
}

/// The name of the thing that raised a failure, and the detail that
/// goes with it.
///
/// v2 carries both in the error object: `What` names the thing that
/// raised the failure, and `Extra` is the detail.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Detail {
    /// The name of the thing that raised the failure.
    pub what: String,
    /// The detail of the failure.
    pub extra: String,
}

/// How a call found the function it calls.
///
/// v2 checks the number of the arguments in two places. A call that the
/// script writes is checked when the script loads, and the failure says
/// the name of the function: "Too few parameters passed to function.
/// \n     Specifically: Abs". A call that goes through a value is checked when
/// the call runs, and the failure is the one of the run: "Missing a
/// required parameter." for a function of the script, and "Too few
/// parameters passed to function." for a built-in.
#[derive(Clone, Copy, PartialEq)]
pub(crate) enum Route {
    /// The script wrote the call, and the name of the function is known
    /// when the script loads.
    Written,
    /// The call goes through a value, and the name of the function is
    /// not known when the script loads.
    ThroughValue,
    /// The call went through the `Call` method of a value of a function.
    ///
    /// v2 names that method in the `What` of the failure of the number
    /// of the arguments, and the call of the value itself does not.
    ThroughTheCall,
}

impl From<RuntimeError> for RuntimeFailure {
    fn from(error: RuntimeError) -> Self {
        RuntimeFailure::Error(error)
    }
}

impl From<Timeout> for RuntimeFailure {
    fn from(timeout: Timeout) -> Self {
        RuntimeFailure::Timeout(timeout)
    }
}

impl From<Flow> for RuntimeFailure {
    fn from(flow: Flow) -> Self {
        RuntimeFailure::Flow(flow)
    }
}

impl From<String> for RuntimeFailure {
    fn from(message: String) -> Self {
        RuntimeFailure::Error(RuntimeError { message, line: 0 })
    }
}
/// The variables of the loops, the ones that the runtime writes where it
/// runs.
///
/// Measured on the binary of v2.0.19: they are there
/// before the first loop runs, and the index is zero and the others are
/// empty.
///
/// The index that the `MinIndex()` and the `MaxIndex()` of the v1 answer.
///
/// Measured on the binary of AutoHotkey v1.1.37.02: an array
/// that has no value at all -- and an object that is not an array -- answers
/// the empty text for the two of them.
fn the_index_of_the_v1(index: Option<i64>) -> Value {
    match index {
        Some(index) => Value::Int(index),
        None => Value::Text("".into()),
    }
}

/// The key of a `HasKey` of the v1, and the kind that it was written with.
///
/// The number of the v1 is its text, and the value that the parser gives
/// does not tell the number from the text: the literal of the argument
/// does.
enum TheKeyOfTheV1 {
    /// A key that is a number: the index of an array, and the name of a
    /// numeric property of an object.
    TheNumber(i64),
    /// A key that is a text: the name of a property.
    TheText(String),
}

/// The index of a key of the v1, when the key is a number.
///
/// The tree reads the key of the `HasKey` as a text, and the text of a
/// number is the number of it: the key and the text of it are the same key
/// in the tree, and two keys in the v1.
fn the_index_of_the_key_of_the_v1(key: &Value) -> Option<i64> {
    match key {
        Value::Int(number) => Some(*number),
        Value::Text(text) => text.trim().parse::<i64>().ok(),
        _ => None,
    }
}

/// The number that a text begins with, when it begins with one.
///
/// The `Critical, 1` of the v1 is the same as the `Critical, On`, and
/// the `Critical, 0` is the same as the `Critical, Off`: the number
/// that the text begins with is the one that counts.
fn the_leading_number_of(text: &str) -> Option<i64> {
    let text = text.trim();
    let bytes = text.as_bytes();
    let mut end = 0;
    if end < bytes.len() && (bytes[end] == b'+' || bytes[end] == b'-') {
        end += 1;
    }
    let start = end;
    while end < bytes.len() && bytes[end].is_ascii_digit() {
        end += 1;
    }
    if end == start {
        return None;
    }
    text[..end].parse::<i64>().ok()
}

/// The first address of a list of images.
///
/// The addresses of the objects are minted from `0x1000`, the ones of the
/// texts from `0x2000_0000`, and the ones of the lists of images from here,
/// so that the three never name the same thing.
const IMAGE_LIST_ADDRESS_BASE: i64 = 0x3000_0000;

// -- the pump of the machine --------------------------------------------------------
//
// The cases are about the order of the things: the hotkey that is pressed
// while a function of the script computes runs at once, and not when the
// function ends.

#[cfg(all(test, feature = "std"))]
mod tests {
    use super::*;
    use crate::desktop::{
        Clipboard, Com, Dialogs, Hotkeys, Keyboard, Machine, Native, Network, Pictures, Pointer,
        Processes, Screen, Sound, Timers, Windows,
    };

    /// A desktop that fires a hotkey, and that does nothing else.
    struct TheFake {
        /// The hotkey that fires, when one is waiting.
        fired: Option<String>,
        /// The message that the machine has, and that arrives when the
        /// script watches it.
        event: Option<String>,
        /// The messages that arrived at the windows of the script.
        arrived: Vec<String>,
        /// The events of the windows of the script that the machine has
        /// for the runtime, and that it gives the first time the runtime
        /// asks for them.
        windows: Vec<String>,
    }

    impl Desktop for TheFake {}
    impl Keyboard for TheFake {
        fn type_text(&mut self, _text: &str) -> Result<String, String> {
            Ok(String::new())
        }
        fn press_key(&mut self, _key: &str, _modifiers: &[String]) -> Result<String, String> {
            Ok(String::new())
        }
    }
    impl Pointer for TheFake {
        fn click(
            &mut self,
            _x: i64,
            _y: i64,
            _button: &str,
            _count: u32,
        ) -> Result<String, String> {
            Ok(String::new())
        }
    }
    impl Screen for TheFake {
        fn capture(
            &mut self,
            _x: i64,
            _y: i64,
            _width: i64,
            _height: i64,
            _kind: &str,
        ) -> Result<String, String> {
            Ok(String::new())
        }
        fn pixel(&mut self, _x: i64, _y: i64) -> Result<String, String> {
            Ok("#000000".to_string())
        }
    }
    impl Windows for TheFake {
        fn gui_events(&mut self) -> Result<Vec<String>, String> {
            let mut events = core::mem::take(&mut self.windows);
            events.append(&mut self.arrived);
            Ok(events)
        }
        /// The script watches a message: the message that the machine had
        /// for that number arrives now.
        fn watch_a_message(&mut self, _number: i64) -> Result<(), String> {
            if let Some(event) = self.event.take() {
                self.arrived.push(event);
            }
            Ok(())
        }
    }
    impl Processes for TheFake {
        fn run(&mut self, _program: &str, _arguments: &str) -> Result<(i32, String, String), String> {
            Ok((0, String::new(), String::new()))
        }
    }
    impl Files for TheFake {
        fn working_directory(&mut self) -> Result<String, String> {
            Ok(String::new())
        }
        fn initial_working_directory(&mut self) -> Result<String, String> {
            Ok(String::new())
        }
    }
    impl Clipboard for TheFake {}
    impl Timers for TheFake {}
    impl Hotkeys for TheFake {
        fn register_hotkey(&mut self, _name: &str) -> Result<String, String> {
            Ok(String::new())
        }
        fn fired_hotkey(&mut self) -> Result<Option<String>, String> {
            Ok(self.fired.take())
        }
    }
    impl Native for TheFake {}
    impl Com for TheFake {}
    impl Pictures for TheFake {}
    impl Network for TheFake {}
    impl Sound for TheFake {}
    impl Machine for TheFake {}
    impl Dialogs for TheFake {}

    /// Run a script of the v1 against the fake, and answer with the report.
    fn run(script: &str) -> Report {
        run_with_events(script, None)
    }

    /// Run a script of the v1 against the fake, and answer with the
    /// report. The fake gives the event of a window once.
    fn run_with_events(script: &str, event: Option<&str>) -> Report {
        let statements =
            crate::parse_with(script, crate::dialect::v1()).expect("the script of the v1 parses");
        let mut desktop = TheFake {
            fired: Some("F1".to_string()),
            event: event.map(|text| text.to_string()),
            arrived: Vec::new(),
            windows: Vec::new(),
        };
        Runtime::new(&mut desktop, Duration::from_secs(60))
            .with_dialect(crate::dialect::v1())
            .run(&statements)
    }

    /// Run a script of the v1 against the fake, and answer with the
    /// report. The fake gives the events of the windows of the script
    /// when the runtime asks for them.
    fn run_with_the_events_of_the_windows(script: &str, events: &[&str]) -> Report {
        let statements =
            crate::parse_with(script, crate::dialect::v1()).expect("the script of the v1 parses");
        let mut desktop = TheFake {
            fired: Some("F1".to_string()),
            event: None,
            arrived: Vec::new(),
            windows: events.iter().map(|text| text.to_string()).collect(),
        };
        Runtime::new(&mut desktop, Duration::from_secs(60))
            .with_dialect(crate::dialect::v1())
            .run(&statements)
    }

    /// The hotkey that is pressed while a function computes runs at once.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the v1 peeks
    /// between the commands, and a function of the script is a command.
    /// The hotkey runs in a thread of its own, and the thread answers
    /// while the function computes -- the body of the hotkey is between
    /// the two writes of the function, and not after them.
    ///
    /// The order of the writes is in the number itself: the write of the
    /// function is a one, the write of the hotkey is a two and the last
    /// write of the function is a three.
    #[test]
    fn the_hotkey_that_is_pressed_while_a_function_computes_runs_at_once() {
        let report = run(
            "out := 0\n\
             theFunction() {\n\
                global out\n\
                out := out * 10 + 1\n\
                Hotkey, F1, theHotkey\n\
                Loop 3 {\n\
                   x := 1\n\
                }\n\
                out := out * 10 + 3\n\
             }\n\
             theHotkey() {\n\
                global out\n\
                out := out * 10 + 2\n\
             }\n\
             theFunction()\n",
        );
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        assert_eq!(
            report.variables.get("out").map(|value| value.to_text()),
            Some("123".to_string())
        );
    }

    /// The body of a hotkey does not write into the locals of the function
    /// that was running when the hotkey was pressed.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the v1 runs the
    /// body of a hotkey in a thread of its own, and the variables of that
    /// thread are the variables of the script. The local of the function
    /// that was running keeps its value, and the write of the body goes
    /// into the global of the script.
    #[test]
    fn the_body_of_a_hotkey_does_not_write_into_the_locals_of_the_function() {
        let report = run(
            "out := 0\n\
             globalMine := 0\n\
             theFunction()\n\
             TheLabel:\n\
                mine := 2\n\
                globalMine := 2\n\
                Return\n\
             theFunction() {\n\
                global out\n\
                global globalMine\n\
                local mine\n\
                mine := 1\n\
                Hotkey, F1, TheLabel\n\
                Loop 3 {\n\
                   x := 1\n\
                }\n\
                out := mine * 10 + globalMine\n\
             }\n",
        );
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        // The local of the function keeps its value (the one), and the
        // global of the script holds the write of the body of the hotkey
        // (the two).
        assert_eq!(
            report.variables.get("out").map(|value| value.to_text()),
            Some("12".to_string())
        );
    }

    /// The message that arrives while the thread is critical is not lost.
    ///
    /// The thread that is critical is not interrupted: the timers and the
    /// hotkeys wait for it to end. The messages of the machine are answered
    /// all the same -- the windows of the script keep working -- and the
    /// handler of the message runs.
    #[test]
    fn the_message_that_arrives_during_a_critical_section_is_not_lost() {
        let report = run_with_events(
            "out := 0\n\
             Handler(wParam, lParam, msg, hwnd) {\n\
                global out\n\
                out := out * 10 + 10\n\
                return\n\
             }\n\
             theFunction() {\n\
                global out\n\
                Critical, on\n\
                OnMessage(0x404, \"Handler\")\n\
                Loop 3 {\n\
                   x := 1\n\
                }\n\
                Critical, off\n\
                out := out + 1\n\
             }\n\
             theFunction()\n",
            Some("message:1028:0:0:0"),
        );
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        // The handler of the message ran (the ten), and the function went
        // on after it (the one).
        assert_eq!(
            report.variables.get("out").map(|value| value.to_text()),
            Some("11".to_string())
        );
    }

    /// The window of the script that is resized runs the label of the
    /// event, and not the function of it.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the label
    /// `PVwinGuiSize` of the script runs when the window `PVwin` of the
    /// script is resized, and it is a **label**: a script that has the
    /// label and the function of the same name runs the label, and the
    /// function is not called.
    ///
    /// The probe is `agentG2-3-both.ahk`, in the probes of the
    /// measurement, and the answer of the v1 is the word `label`.
    #[test]
    fn the_window_that_is_resized_runs_the_label_of_the_event() {
        let report = run_with_the_events_of_the_windows(
            "out := 0\n\
             theFunction()\n\
             Return\n\
             PVwinGuiSize:\n\
                out := out * 10 + 1\n\
                Return\n\
             PVwinGuiSize(GuiHwnd, EventInfo, Width, Height) {\n\
                global out\n\
                out := out * 10 + 2\n\
             }\n\
             theFunction() {\n\
                global out\n\
                Loop 3 {\n\
                   x := 1\n\
                }\n\
             }\n",
            &["v1size:PVwinGuiSize:0:300:200:4321"],
        );
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        // The label ran (the one), and the function of the same name did
        // not (the two).
        assert_eq!(
            report.variables.get("out").map(|value| value.to_text()),
            Some("1".to_string())
        );
    }

    /// The label of the event reads the facts of the event in the built-in
    /// variables.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the label
    /// `PVwinGuiSize` of a window that is resized reads `A_GuiWidth` and
    /// `A_GuiHeight` with the size of the client area of the window,
    /// `A_EventInfo` and `ErrorLevel` with the kind of the change, and
    /// `A_Gui` with the name of the window. The probe is
    /// `agentG2-1-label.ahk`, in the probes of the measurement.
    #[test]
    fn the_label_of_the_event_reads_the_facts_of_the_event() {
        let report = run_with_the_events_of_the_windows(
            "out := 0\n\
             theFunction()\n\
             Return\n\
             PVwinGuiSize:\n\
                out := A_GuiWidth \",\" A_GuiHeight \",\" A_EventInfo \",\" ErrorLevel \",\" A_Gui\n\
                Return\n\
             theFunction() {\n\
                Loop 3 {\n\
                   x := 1\n\
                }\n\
             }\n",
            &["v1size:PVwinGuiSize:0:300:200:4321"],
        );
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        assert_eq!(
            report.variables.get("out").map(|value| value.to_text()),
            Some("300,200,0,0,PVwin".to_string())
        );
    }

    /// The function of the event runs when the label of it is not there,
    /// and it is called with the handle of the window, the kind of the
    /// change and the size of the client area of it.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the CHM of the
    /// v1.1.37.02 says of the event of the window that is resized: "If
    /// GuiSize is a function, its parameters are as follows: GuiSize(GuiHwnd,
    /// EventInfo, Width, Height)". The probe is `agentG2-2-func.ahk`, in the
    /// probes of the measurement.
    #[test]
    fn the_function_of_the_event_runs_when_the_label_of_it_is_not_there() {
        let report = run_with_the_events_of_the_windows(
            "out := 0\n\
             theFunction()\n\
             Return\n\
             PVwinGuiSize(GuiHwnd, EventInfo, Width, Height) {\n\
                global out\n\
                out := GuiHwnd \",\" EventInfo \",\" Width \",\" Height\n\
             }\n\
             theFunction() {\n\
                Loop 3 {\n\
                   x := 1\n\
                }\n\
             }\n",
            &["v1size:PVwinGuiSize:0:300:200:4321"],
        );
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        assert_eq!(
            report.variables.get("out").map(|value| value.to_text()),
            Some("4321,0,300,200".to_string())
        );
    }

    /// The window of the script without a name runs the label `GuiSize`.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the window of the
    /// script without a name has the `Gui` for the prefix of the labels of
    /// it, and the label of the event of the resize is the `GuiSize`. The
    /// probe is `agentG2-5-default.ahk`, in the probes of the measurement.
    #[test]
    fn the_window_of_the_script_without_a_name_runs_the_label_guisize() {
        let report = run_with_the_events_of_the_windows(
            "out := 0\n\
             theFunction()\n\
             Return\n\
             GuiSize:\n\
                out := A_Gui\n\
                Return\n\
             theFunction() {\n\
                Loop 3 {\n\
                   x := 1\n\
                }\n\
             }\n",
            &["v1size:GuiSize:0:300:200:4321"],
        );
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        // The name of the window of the script without a name is the
        // number of it.
        assert_eq!(
            report.variables.get("out").map(|value| value.to_text()),
            Some("1".to_string())
        );
    }

    /// The window of the script that is resized with a client area of zero
    /// is not an event of the v1.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the v1 calls the
    /// label of the event once for the `Gui, Show` and once for every
    /// resize of the window, and never with a client area of zero.
    #[test]
    fn the_window_that_is_resized_with_a_client_area_of_zero_runs_no_label() {
        let report = run_with_the_events_of_the_windows(
            "out := 0\n\
             theFunction()\n\
             Return\n\
             PVwinGuiSize:\n\
                out := out * 10 + 1\n\
                Return\n\
             theFunction() {\n\
                Loop 3 {\n\
                   x := 1\n\
                }\n\
             }\n",
            &["v1size:PVwinGuiSize:0:0:0:4321"],
        );
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        assert_eq!(
            report.variables.get("out").map(|value| value.to_text()),
            Some("0".to_string())
        );
    }

    /// The `for` of the v1 walks the own properties of an object.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the
    /// `for k, v in o` of the `{a: 1, b: 2}` has two turns, and the key and
    /// the value of them are the name of the property and the value under
    /// it. The names come in the order of their names, and the numeric
    /// ones come before the text ones.
    #[test]
    fn the_for_of_the_v1_walks_the_properties_of_an_object() {
        let report = run("o := {b: 1, a: 2}\n\
                          keys := \"\"\n\
                          values := \"\"\n\
                          turns := 0\n\
                          for k, v in o {\n\
                              keys := keys k \" \"\n\
                              values := values v \" \"\n\
                              turns := turns + 1\n\
                          }\n");
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        assert_eq!(
            report.variables.get("keys").map(|value| value.to_text()),
            Some("a b ".to_string())
        );
        assert_eq!(
            report.variables.get("values").map(|value| value.to_text()),
            Some("2 1 ".to_string())
        );
        assert_eq!(
            report.variables.get("turns").map(|value| value.to_text()),
            Some("2".to_string())
        );
    }

    /// The `for` of the v1 walks the items of an array and the properties
    /// of it.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the
    /// `for k, v in a` of the `[1, 2]` has two turns, and the keys of them
    /// are the indexes. The array with the property "name" has a turn for
    /// the property too, and the turn of the property comes after the
    /// turns of the items.
    #[test]
    fn the_for_of_the_v1_walks_the_items_and_the_properties_of_an_array() {
        let report = run("a := [1, 2]\n\
                          a.name := \"x\"\n\
                          keys := \"\"\n\
                          values := \"\"\n\
                          for k, v in a {\n\
                              keys := keys k \" \"\n\
                              values := values v \" \"\n\
                          }\n");
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        assert_eq!(
            report.variables.get("keys").map(|value| value.to_text()),
            Some("1 2 name ".to_string())
        );
        assert_eq!(
            report.variables.get("values").map(|value| value.to_text()),
            Some("1 2 x ".to_string())
        );
    }

    /// The `for` of the v1 over a value that is not an object has no turn,
    /// and it does not fail.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the `for i in 5`
    /// of the v1 has no turn and it does not fail.
    #[test]
    fn the_for_of_the_v1_over_a_value_that_is_not_an_object_has_no_turn() {
        let report = run("turns := 0\n\
                          for k, v in 5\n\
                              turns := turns + 1\n");
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        assert_eq!(
            report.variables.get("turns").map(|value| value.to_text()),
            Some("0".to_string())
        );
    }

    /// The `HasKey` of the v1 tells a number from its text.
    ///
    /// Measured on the binary of AutoHotkey v1.1.37.02: the `[1, 2]` has
    /// the key 1 and has not the key "1", and the key that is a text is the
    /// name of a property.
    #[test]
    fn the_haskey_of_the_v1_tells_a_number_from_its_text() {
        let report = run("a := [1, 2]\n\
                          keynumber := a.HasKey(1)\n\
                          keytext := a.HasKey(\"1\")\n\
                          keymissing := a.HasKey(5)\n\
                          keyproperty := 0\n\
                          a.name := \"x\"\n\
                          keyproperty := a.HasKey(\"name\")\n");
        assert!(report.ok, "{:?} at line {:?}", report.error, report.error_line);
        assert_eq!(
            report.variables.get("keynumber").map(|value| value.to_text()),
            Some("1".to_string())
        );
        assert_eq!(
            report.variables.get("keytext").map(|value| value.to_text()),
            Some("0".to_string())
        );
        assert_eq!(
            report.variables.get("keymissing").map(|value| value.to_text()),
            Some("0".to_string())
        );
        assert_eq!(
            report.variables.get("keyproperty").map(|value| value.to_text()),
            Some("1".to_string())
        );
    }
}
